// Clean and aggregate - NO LINKS constraint
const allHtml = $input.all.map(i => i.json).join(' ');
// Extract headlines via regex (simplified)
const titleRegex = /<h[2-4][^>]*>(.*?)<\/h[2-4]>/gi;
let titles = [];
let match;
while ((match = titleRegex.exec(allHtml)) !== null) {
  let t = match[1].replace(/<[^>]*>/g, '').trim();
  t = t.replace(/http\S+|www\S+/g, ''); // NO LINKS
  if (t.length > 15 && t.length < 250) titles.push(t);
}
// Deduplicate
titles = [...new Set(titles)].slice(0,20);
return [{ json: { titles, fetched_at: new Date().toISOString(), count: titles.length } }];

