// Validate NO LINKS and format
const data = $input.first().json.message?.content ? JSON.parse($input.first().json.message.content) : $input.first().json;
function cleanNoLinks(t){ return t.replace(/http\S+|www\S+/g, '').replace(/\[.*?\]\(.*?\)/g, '').trim(); }
let result = {
  headline: cleanNoLinks(data.headline || 'اہم خبر'),
  headline_roman: cleanNoLinks(data.headline_roman || data.headline),
  urdu_bullets: (data.urdu_bullets||[]).map(cleanNoLinks).slice(0,5),
  roman_urdu_bullets: (data.roman_urdu_bullets||[]).map(cleanNoLinks).slice(0,5),
  category: data.category || 'Hyderabad',
  date_str: new Date().toLocaleDateString('en-IN', {day:'numeric', month:'long', year:'numeric'}),
  time_str: new Date().toLocaleTimeString('en-IN', {hour:'numeric', minute:'2-digit', hour12:true})
};
return [{json: result}];

